UPDATE businesses SET description = 'Kwik Spar Flamingo Square is the neighbourhood SPAR in Flamingo Square Centre, on the corner of Blaauwberg Road and Study Street in Table View. It is a handy daily grocery stop for local families and for commuters heading home along Blaauwberg Road.

Fresh food is the store’s strength. An in-store bakery turns out fresh bread and baked treats, the hot deli counter serves ready-made meals for an easy lunch or supper, and the fresh produce section includes a good choice of organic fruit and vegetables. Pantry staples and household essentials fill the rest of the shelves, so a quick top-up shop can easily cover the whole list. Shoppers mention the friendly staff and the neat, well-organised layout, and the centre has secure free parking. The store keeps long trading hours, staying open late into the evening every day. Kwik Spar is at Shop 15, Flamingo Square Centre, corner Study Street and Blaauwberg Road, Table View.', description_enriched_at = datetime('now') WHERE slug = 'kwik-spar-flamingo-square-table-view' AND description = 'Kwik Spar Flamingo Square is a convenience supermarket inside Flamingo Square, Table View, trading daily.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
